    <?php
//php program to find the max sum of
// numbers whose lcm is n

// Returns maximum sum of numbers with
// LCM as N
function maxSumLCM($n)
{
    $max_sum = 0; // Initialize result

    // Finding a divisor of n and adding
    // it to max_sum
    for ($i = 1; $i * $i <= $n; $i++)
    {
        if ($n % $i == 0)
        {
            $max_sum += $i;
            if ($n/$i != $i)
                $max_sum += ($n / $i);
        }
    }

    return $max_sum;
}

// Driver code
$n = 2;
echo MaxSumLCM($n), "\n";

